<?php declare(strict_types=1); session_start(); require_once __DIR__.'/includes/config.php'; $hospital_id=(int)($_GET['hospital_id']??0); if($hospital_id<=0){die('Invalid hospital.');} $st=mysqli_prepare($conn,"SELECT hospital_id,hospital_name FROM hospital_registration WHERE hospital_id=? LIMIT 1"); mysqli_stmt_bind_param($st,'i',$hospital_id); mysqli_stmt_execute($st); $r=mysqli_stmt_get_result($st); $h=$r?mysqli_fetch_assoc($r):null; if($r)mysqli_free_result($r); mysqli_stmt_close($st); if(!$h)die('Hospital not found.'); $_SESSION['qr_hospital_id']=$hospital_id; $_SESSION['qr_hospital_name']=$h['hospital_name']; if(isset($_SESSION['patient_auth']['logged_in']) && $_SESSION['patient_auth']['logged_in']===true){ header('Location: /Hospital_Management_System/patient_portal/appointments/register_hospital.php?hospital_id='.$hospital_id); } else { header('Location: /Hospital_Management_System/mobile/login.php?qr_hospital='.$hospital_id); } exit; ?>